const LEAGUE_KEYS = ["PL","LAL","BUN","SA","L1"];

// =============================================================
// LEAGUE HISTORY COMPONENT (5大リーグ共通) — サイドバー付き期間選択
// =============================================================

function seasonToYear(s) {
  // "46/47" → 1946, "00/01" → 2000, "25/26" → 2025
  const yr = parseInt(s.slice(0,2));
  return yr >= 26 ? 1900 + yr : 2000 + yr;
}

// CL圏・降格圏のカラー定義
const ZONE_COLORS = {
  cl:   "#00B4D8",  // CL
  el:   "#4CAF50",  // EL
  ecl:  "#8BC34A",  // ECL
  rel:  "#E63946",  // 降格
  play: "#FF8C00",  // プレーオフ
};

// シーズン成績表コンポーネント
function SeasonTable({ leagueKey, cfg, POSITIONS, TEAM_NAMES_JP, visibleSeasons, estimatePts }) {
  const ALL_TEAMS = Object.keys(POSITIONS);
  // 全シーズン（グラフの表示期間とは独立）
  const ALL_SEASONS = Object.keys(POSITIONS[ALL_TEAMS[0]].data);
  const latestSeason = ALL_SEASONS[ALL_SEASONS.length - 1];
  const [selSeason, setSelSeason] = useState(latestSeason);

  const season = ALL_SEASONS.includes(selSeason) ? selSeason : latestSeason;

  // そのシーズンの全出場クラブを順位順（収録クラブのみ、順位データがあるもの全て）
  const rows = useMemo(() => {
    // 収録クラブの行
    const collected = ALL_TEAMS
      .filter(t => POSITIONS[t]?.data[season] != null)
      .map(team => {
        const realPts = cfg.seasonPts?.[team]?.[season];
        const origPos = POSITIONS[team].data[season];
        const estPts = estimatePts(origPos, season, leagueKey);
        const pts = realPts != null ? realPts : estPts;
        const isReal = realPts != null;
        return { team, name: TEAM_NAMES_JP[team]||team, pts, isReal, isExtra: false, color: POSITIONS[team]?.color||"#888", origPos };
      });

    // 非収録クラブ（extraClubs）をマージ（重複除去）
    const collectedNames = new Set(collected.map(c => c.name));
    const extra = (cfg.extraClubs?.[season] || [])
      .filter(e => !collectedNames.has(e.name))
      .map(e => ({ team: null, name: e.name, pts: e.pts, isReal: true, isExtra: true, color: "#555", origPos: null }));

    // 全クラブを勝ち点降順でソート、同点は収録クラブのorigPosで解決
    const all = [...collected, ...extra].sort((a,b) => {
      if ((b.pts||0) !== (a.pts||0)) return (b.pts||0) - (a.pts||0);
      // 同点: origPosが小さい方が上
      if (a.origPos && b.origPos) return a.origPos - b.origPos;
      if (a.origPos) return -1;
      if (b.origPos) return 1;
      return 0;
    });

    // 1から連番で順位付与
    return all.map((row, i) => ({ ...row, pos: i + 1 }));
  }, [season]);

  // リーグ別ゾーン設定
  const zoneConfig = {
    PL:  { cl:[1,4], el:[5,6], ecl:[7,7], rel:[18,20] },
    LAL: { cl:[1,4], el:[5,6], ecl:[7,7], rel:[18,20] },
    BUN: { cl:[1,4], el:[5,5], ecl:[6,6], rel:[16,18] },
    SA:  { cl:[1,4], el:[5,6], ecl:[7,7], rel:[18,20] },
    L1:  { cl:[1,3], el:[4,5], ecl:[6,6], rel:[16,18] },
  };
  const zones = zoneConfig[leagueKey] || {};

  function getZoneColor(pos) {
    if (zones.cl  && pos >= zones.cl[0]  && pos <= zones.cl[1])  return ZONE_COLORS.cl;
    if (zones.el  && pos >= zones.el[0]  && pos <= zones.el[1])  return ZONE_COLORS.el;
    if (zones.ecl && pos >= zones.ecl[0] && pos <= zones.ecl[1]) return ZONE_COLORS.ecl;
    if (zones.rel && pos >= zones.rel[0] && pos <= zones.rel[1]) return ZONE_COLORS.rel;
    return null;
  }

  // 収録外クラブ（順位はあるが名前データがないクラブ）の補完
  // 在籍クラブ数を計算してギャップを検出
  const presentCount = rows.length;
  const yr = parseInt(season.slice(0,2));
  const year = yr >= 26 ? 1900+yr : 2000+yr;
  const expectedCount = leagueKey === "BUN" ? 18 : (year <= 1994 && leagueKey==="PL") ? 22 : 20;
  const missingCount = expectedCount - presentCount;

  return (
    <div style={{ background:"#0b0c14",border:"1px solid #1a1a28",borderRadius:4,padding:"14px 16px",marginBottom:12 }}>
      {/* シーズン選択 */}
      <div style={{ display:"flex",alignItems:"center",gap:10,marginBottom:12,flexWrap:"wrap" }}>
        <span style={{ fontSize:10,color:"#555",letterSpacing:2 }}>成績表</span>
        <select value={season} onChange={e => setSelSeason(e.target.value)} style={{
          background:"#111",color:"#FFD700",border:"1px solid #333",borderRadius:3,
          padding:"4px 10px",fontSize:12,fontFamily:"'IBM Plex Mono',monospace",cursor:"pointer",
          fontWeight:700,
        }}>
          {[...ALL_SEASONS].reverse().map(s => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
        <span style={{ fontSize:9,color:"#444" }}>
          {presentCount}クラブ収録
          {missingCount > 0 && <span style={{ color:"#333" }}>（+{missingCount}クラブ非収録）</span>}
        </span>
        {/* ゾーン凡例 */}
        <div style={{ display:"flex",gap:8,marginLeft:"auto",flexWrap:"wrap",alignItems:"center" }}>
          {[["cl","CL"],["el","EL"],["ecl","ECL"],["rel","降格"]].map(([k,l])=>(
            zones[k] && (
              <div key={k} style={{ display:"flex",alignItems:"center",gap:3 }}>
                <div style={{ width:3,height:14,background:ZONE_COLORS[k],borderRadius:2 }} />
                <span style={{ fontSize:9,color:"#555" }}>{l}</span>
              </div>
            )
          ))}
          <span style={{ fontSize:9,color:"#333" }}>🟡実 ⚪推計</span>
        </div>
      </div>

      {/* テーブル */}
      <div style={{ overflowX:"auto" }}>
        <table style={{ borderCollapse:"collapse",width:"100%",fontFamily:"'IBM Plex Mono',monospace",fontSize:11 }}>
          <thead>
            <tr style={{ borderBottom:"1px solid #252535" }}>
              {["#","チーム","勝","分","負","点"].map((h,i) => (
                <th key={h} style={{
                  textAlign: i<=1 ? "left" : "right",
                  color:"#555",padding:"4px 8px",fontSize:10,fontWeight:400,
                  minWidth: i===1 ? 110 : 28,
                }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map(({ team, name, pos, pts, isReal, isExtra, color }) => {
              const c = color || "#888";
              const zoneColor = getZoneColor(pos);
              const isChamp = pos === 1;
              const lightColors = ["#FFFFFF","#F0F0F0","#E8E8E8","#FDE100","#FFE600","#FFD700","#FDDD00"];
              const textOnColor = lightColors.includes(c) ? "#000" : c;
              const threePtYear = { PL:1982,LAL:1996,BUN:1996,SA:1995,L1:1995 }[leagueKey]||1982;
              const is3pt = year >= threePtYear;
              const numTeams = leagueKey==="BUN" ? 18 : (year<=1994&&leagueKey==="PL") ? 22 : 20;
              const games = (numTeams-1)*2;
              const wEst = is3pt ? Math.round(pts/3*0.78) : Math.round(pts/2*0.78);
              const lEst = Math.max(0, Math.round((games - wEst) * (pos/numTeams) * 0.8));
              const dEst = Math.max(0, games - wEst - lEst);
              return (
                <tr key={team||name} style={{
                  borderBottom:"1px solid #0d0d14",
                  background: isChamp ? "#FFD70008" : "transparent",
                  opacity: isExtra ? 0.7 : 1,
                }}>
                  <td style={{ padding:"6px 8px",textAlign:"left",whiteSpace:"nowrap" }}>
                    <div style={{ display:"flex",alignItems:"center",gap:6 }}>
                      <div style={{ width:3,height:20,background:zoneColor||"transparent",borderRadius:2,flexShrink:0 }} />
                      <span style={{ color:isChamp?"#FFD700":"#555",fontSize:11,fontWeight:isChamp?700:400 }}>{pos}</span>
                    </div>
                  </td>
                  <td style={{ padding:"6px 8px",textAlign:"left" }}>
                    <span style={{ color: isExtra ? "#777" : textOnColor, fontSize:11, fontWeight:pos<=4&&!isExtra?700:400 }}>
                      {isChamp?"🏆 ":""}{name}
                      {isExtra && <span style={{ fontSize:8,color:"#444",marginLeft:4 }}>*</span>}
                    </span>
                  </td>
                  <td style={{ padding:"6px 8px",textAlign:"right",color:"#06D6A0",fontSize:11 }}>{isReal&&!isExtra ? wEst : "–"}</td>
                  <td style={{ padding:"6px 8px",textAlign:"right",color:"#888",fontSize:11 }}>{isReal&&!isExtra ? dEst : "–"}</td>
                  <td style={{ padding:"6px 8px",textAlign:"right",color:"#E63946",fontSize:11 }}>{isReal&&!isExtra ? lEst : "–"}</td>
                  <td style={{ padding:"6px 8px",textAlign:"right" }}>
                    <span style={{
                      color: isExtra ? "#555" : (isReal ? "#FFD700" : "#555"),
                      fontWeight: pos<=4&&!isExtra ? 700 : 400,
                      fontSize:12,
                    }}>{pts}{(!isReal&&!isExtra) ? "※" : ""}</span>
                  </td>
                </tr>
              );
            })}
            {/* 残り非収録クラブのプレースホルダー（名前不明分） */}
            {missingCount > rows.filter(r=>!r.isExtra).length - ALL_TEAMS.filter(t=>POSITIONS[t]?.data[season]!=null).length
              ? null
              : Array.from({length: Math.max(0, expectedCount - rows.length)},(_,i) => {
              const fakePos = rows.length + i + 1;
              const zoneColor = getZoneColor(fakePos);
              return (
                <tr key={`unknown-${i}`} style={{ borderBottom:"1px solid #0d0d14",opacity:0.3 }}>
                  <td style={{ padding:"6px 8px" }}>
                    <div style={{ display:"flex",alignItems:"center",gap:6 }}>
                      <div style={{ width:3,height:20,background:zoneColor||"transparent",borderRadius:2,flexShrink:0 }} />
                      <span style={{ color:"#333",fontSize:11 }}>{fakePos}</span>
                    </div>
                  </td>
                  <td style={{ padding:"6px 8px",color:"#222",fontSize:11 }}>（不明）</td>
                  <td colSpan={4} style={{ padding:"6px 8px",textAlign:"right",color:"#1a1a1a",fontSize:10 }}>–</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div style={{ fontSize:9,color:"#333",marginTop:8 }}>
        ※ 勝ち点は実データ、勝/分/負は推計 ／ グラフの表示期間とは独立してシーズン選択可
      </div>
    </div>
  );
}

function LeagueHistoryView({ leagueKey }) {
  const cfg = LEAGUE_CONFIG[leagueKey];
  const POSITIONS = cfg.positions;
  const TEAM_NAMES_JP = cfg.names;
  const BIG_GROUP = cfg.bigGroup;
  const ALL_TEAMS = Object.keys(POSITIONS);
  const ALL_SEASONS = Object.keys(POSITIONS[ALL_TEAMS[0]].data);

  // 全シーズンの年範囲
  const allYears = ALL_SEASONS.map(seasonToYear);
  const minYear = Math.min(...allYears);
  const maxYear = Math.max(...allYears);

  const [selected, setSelected] = useState(new Set(BIG_GROUP));
  const [zoomTop6, setZoomTop6] = useState(false);
  const [yearFrom, setYearFrom] = useState(1992);
  const [yearTo, setYearTo] = useState(maxYear);
  const [subView, setSubView] = useState("positions"); // "positions" | "cumpts" | "wdl"

  const toggle = (team) => setSelected(prev => {
    const n = new Set(prev); n.has(team) ? n.delete(team) : n.add(team); return n;
  });

  const visibleSeasons = useMemo(() =>
    ALL_SEASONS.filter(s => {
      const y = seasonToYear(s);
      return y >= yearFrom && y <= yearTo;
    }),
    [yearFrom, yearTo, ALL_SEASONS]
  );

  const chartData = useMemo(() => visibleSeasons.map(season => {
    const row = { season };
    [...selected].forEach(team => { row[team] = POSITIONS[team]?.data[season]; });
    return row;
  }), [selected, visibleSeasons]);

  const trophies = useMemo(() => {
    const result = {};
    [...selected].forEach(team => {
      if (!POSITIONS[team]) return;
      let titles=0, runners=0, top4=0;
      Object.entries(POSITIONS[team].data).forEach(([s,pos]) => {
        if (pos === 1) titles++;
        if (pos === 2) runners++;
        if (pos != null && pos <= 4) top4++;
      });
      result[team] = { titles, runners, top4 };
    });
    return result;
  }, [selected]);

  // 累積勝ち点データ（visibleSeasons範囲）
  const cumPtsData = useMemo(() => {
    const teams = [...selected].filter(t => POSITIONS[t]);
    const cumByTeam = {};
    teams.forEach(t => { cumByTeam[t] = 0; });
    return visibleSeasons.map(season => {
      const row = { season };
      teams.forEach(t => {
        const pos = POSITIONS[t].data[season];
        // 実データ優先、なければ推計
        const realPts = cfg.seasonPts?.[t]?.[season];
        const pts = realPts != null ? realPts : estimatePts(pos, season, leagueKey);
        cumByTeam[t] += pts;
        row[t] = cumByTeam[t];
      });
      return row;
    });
  }, [selected, visibleSeasons]);

  // 累積勝ち点ツールチップ
  const CumTip = ({ active, payload, label }) => {
    if (!active || !payload?.length) return null;
    const s = [...payload].filter(p => p.value != null).sort((a,b) => b.value - a.value);
    return (
      <div style={{ background:"#0a0a14",border:"1px solid #252535",borderRadius:4,padding:"10px 14px",fontFamily:"'IBM Plex Mono',monospace",fontSize:11,minWidth:210 }}>
        <div style={{ color:"#888",marginBottom:6,fontSize:10 }}>{label} 累計</div>
        {s.map(p => {
          const realPts = cfg.seasonPts?.[p.dataKey]?.[label];
          const pos = POSITIONS[p.dataKey]?.data[label];
          const thisPts = realPts != null ? realPts : estimatePts(pos, label, leagueKey);
          const isReal = realPts != null;
          return (
            <div key={p.dataKey} style={{ display:"flex",justifyContent:"space-between",gap:10,color:p.color,marginBottom:2,alignItems:"center" }}>
              <span style={{ flex:1 }}>{TEAM_NAMES_JP[p.dataKey] || p.dataKey}</span>
              <span style={{ fontSize:9,color: isReal?"#FFD70099":"#55555599",minWidth:36,textAlign:"right" }}>
                +{thisPts}{isReal?"":"※"}
              </span>
              <span style={{ fontWeight:700,minWidth:44,textAlign:"right" }}>{p.value}</span>
            </div>
          );
        })}
        <div style={{ fontSize:9,color:"#333",marginTop:4,borderTop:"1px solid #1a1a28",paddingTop:4 }}>
          右: 累計 pt ／ 中: このシーズン{s.some(p => cfg.seasonPts?.[p.dataKey]?.[label] == null) ? "（※推計含む）":""}
        </div>
      </div>
    );
  };

  const Tooltip2 = ({ active, payload, label }) => {
    if (!active || !payload?.length) return null;
    const sorted = [...payload].filter(p => p.value != null).sort((a,b) => a.value - b.value);
    return (
      <div style={{ background:"#0a0a14",border:"1px solid #252535",borderRadius:4,padding:"10px 14px",fontFamily:"'IBM Plex Mono',monospace",fontSize:11,minWidth:210 }}>
        <div style={{ color:"#888",marginBottom:6,fontSize:10,letterSpacing:2 }}>{label}</div>
        {sorted.map(p => {
          const realPts = cfg.seasonPts?.[p.dataKey]?.[label];
          const estPts = estimatePts(p.value, label, leagueKey);
          const pts = realPts != null ? realPts : estPts;
          const isReal = realPts != null;
          return (
            <div key={p.dataKey} style={{ display:"flex",justifyContent:"space-between",gap:10,color:p.color,marginBottom:2,alignItems:"center" }}>
              <span style={{ flex:1 }}>{TEAM_NAMES_JP[p.dataKey] || p.dataKey}</span>
              <span style={{ fontWeight:700,minWidth:36,textAlign:"right" }}>{p.value===1?"🏆 ":p.value<=4?"✓ ":""}{p.value}位</span>
              <span style={{ fontSize:10,minWidth:50,textAlign:"right",
                color: isReal ? "#FFD700" : "#666",
                fontFamily:"'IBM Plex Mono',monospace",fontWeight: isReal ? 700 : 400,
              }}>{pts}pt{isReal ? "" : "※"}</span>
            </div>
          );
        })}
        {sorted.some(p => cfg.seasonPts?.[p.dataKey]?.[label] == null && p.value != null) && (
          <div style={{ fontSize:9,color:"#444",marginTop:4,borderTop:"1px solid #1a1a28",paddingTop:4 }}>※ 推計値</div>
        )}
      </div>
    );
  };

  return (
    <div>
      {/* ── 期間コントロール（常時表示） ── */}
      <div style={{
        background:"#0b0c14", border:"1px solid #1a1a28", borderRadius:4,
        padding:"12px 16px", marginBottom:12,
      }}>
        <div style={{ display:"flex", gap:12, flexWrap:"wrap", alignItems:"center" }}>
          <span style={{ fontSize:10, color:"#9B5DE5", letterSpacing:2, fontWeight:700, flexShrink:0 }}>表示期間</span>
          <div style={{ display:"flex", alignItems:"center", gap:8, flex:1, minWidth:180 }}>
            <span style={{ fontSize:10, color:"#555", flexShrink:0 }}>開始</span>
            <input type="range" min={minYear} max={yearTo - 1} value={yearFrom}
              onChange={e => setYearFrom(Number(e.target.value))}
              style={{ flex:1, accentColor:"#9B5DE5" }} />
            <span style={{ fontSize:11, color:"#FFD700", fontFamily:"'IBM Plex Mono',monospace", fontWeight:700, minWidth:36, textAlign:"right" }}>{yearFrom}</span>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:8, flex:1, minWidth:180 }}>
            <span style={{ fontSize:10, color:"#555", flexShrink:0 }}>終了</span>
            <input type="range" min={yearFrom + 1} max={maxYear} value={yearTo}
              onChange={e => setYearTo(Number(e.target.value))}
              style={{ flex:1, accentColor:"#9B5DE5" }} />
            <span style={{ fontSize:11, color:"#FFD700", fontFamily:"'IBM Plex Mono',monospace", fontWeight:700, minWidth:36, textAlign:"right" }}>{yearTo}</span>
          </div>
          <div style={{ display:"flex", gap:4, flexWrap:"wrap", alignItems:"center" }}>
            {[
              { label:"全期間", from:minYear, to:maxYear },
              { label:"〜1991", from:minYear, to:1991 },
              { label:"1990〜", from:1990, to:maxYear },
              { label: leagueKey==="PL" ? "PL時代" : "近年", from:1992, to:maxYear },
              { label:"2000〜", from:2000, to:maxYear },
              { label:"2010〜", from:2010, to:maxYear },
            ].map(({ label, from, to }) => {
              const isActive = yearFrom===from && yearTo===to;
              return (
                <button key={label} onClick={() => { setYearFrom(from); setYearTo(to); }} style={{
                  background: isActive ? "#9B5DE5" : "#111",
                  color: isActive ? "#fff" : "#555",
                  border: `1px solid ${isActive ? "#9B5DE5" : "#333"}`,
                  borderRadius:3, padding:"3px 8px", fontSize:10, cursor:"pointer",
                  fontFamily:"'Noto Sans JP',sans-serif",
                }}>{label}</button>
              );
            })}
            <span style={{ fontSize:9, color:"#333" }}>{visibleSeasons.length}s</span>
          </div>
        </div>
      </div>

      {/* ── メインコンテンツ ── */}
      <div>
        {/* Sub-view tabs: 歴代順位 / 累積勝ち点 */}
        <div style={{ display:"flex", justifyContent:"center", gap:6, marginBottom:12 }}>
          {[
            ["positions", "📊 歴代順位"],
            ["cumpts",    "📈 累積勝ち点"],
          ].map(([key, label]) => (
            <button key={key} onClick={() => setSubView(key)} style={{
              background: subView===key ? "#FFD700" : "#111",
              color: subView===key ? "#000" : "#666",
              border:`1px solid ${subView===key?"#FFD700":"#333"}`,
              borderRadius:3, padding:"5px 14px", fontSize:11, cursor:"pointer",
              fontFamily:"'Noto Sans JP',sans-serif", fontWeight: subView===key ? 700 : 400,
            }}>{label}</button>
          ))}
        </div>

        {/* Quick select */}
        <div style={{ display:"flex",justifyContent:"center",gap:6,marginBottom:8,flexWrap:"wrap" }}>
          <button onClick={() => setSelected(new Set(BIG_GROUP))} style={qbtn("#9B5DE5")}>{cfg.bigLabel}だけ</button>
          <button onClick={() => setSelected(new Set(ALL_TEAMS.filter(t => !BIG_GROUP.includes(t))))} style={qbtn("#F5A623")}>{cfg.bigLabel}オフ</button>
          <button onClick={() => setSelected(new Set(ALL_TEAMS))} style={qbtn("#06D6A0")}>全部選択</button>
          <button onClick={() => setSelected(new Set())} style={qbtn("#555", true)}>全解除</button>
        </div>

        {/* Team toggles */}
        <div style={{ display:"flex",justifyContent:"center",gap:5,marginBottom:10,flexWrap:"wrap" }}>
          {ALL_TEAMS.map(team => {
            const on = selected.has(team);
            const c = POSITIONS[team]?.color || "#888";
            const lightColors = ["#FFFFFF","#FDE100","#FDDD00","#FFE600","#FFD700","#FFC107","#FFC0CB","#A8E10C","#76FF03"];
            return (
              <button key={team} onClick={() => toggle(team)} style={{
                background: on ? c : "#111",
                color: on ? (lightColors.includes(c) ? "#000" : "#fff") : "#555",
                border:`1px solid ${on?c:"#222"}`,
                borderRadius:3,padding:"3px 8px",fontSize:10,cursor:"pointer",
                fontFamily:"'Noto Sans JP',sans-serif",fontWeight:on?700:400,
              }}>{TEAM_NAMES_JP[team] || team}</button>
            );
          })}
        </div>

        {/* ── 歴代順位ビュー ── */}
        {subView === "positions" && (<>

        {/* Zoom */}
        <div style={{ display:"flex",justifyContent:"center",gap:8,marginBottom:14 }}>
          <button onClick={() => setZoomTop6(v => !v)} style={{
            background: zoomTop6 ? "#9B5DE5" : "#111", color: zoomTop6 ? "#fff" : "#555",
            border:`1px solid ${zoomTop6?"#9B5DE5":"#222"}`,
            borderRadius:3,padding:"4px 14px",fontSize:11,cursor:"pointer",
            fontFamily:"'Noto Sans JP',sans-serif",
          }}>{zoomTop6 ? "✓ 上位6位ズーム中" : "上位6位ズーム"}</button>
        </div>

        {/* Chart */}
        <div style={{ background:"#0b0c14",border:"1px solid #1a1a28",borderRadius:4,padding:"20px 8px 12px 0",marginBottom:16 }}>
          <ResponsiveContainer width="100%" height={420}>
            <LineChart data={chartData} margin={{ top:8,right:24,left:0,bottom:30 }}>
              <CartesianGrid stroke="#131320" strokeDasharray="3 3" />
              <XAxis dataKey="season"
                tick={{ fill:"#555",fontSize:9,fontFamily:"'IBM Plex Mono',monospace" }}
                tickLine={false} axisLine={{ stroke:"#252535" }}
                angle={-45} textAnchor="end"
                interval={Math.max(0, Math.floor(visibleSeasons.length / 24))} />
              <YAxis reversed
                domain={zoomTop6 ? [1,6] : [1,cfg.yMax]}
                ticks={zoomTop6 ? [1,2,3,4,5,6] : cfg.yTicks}
                tick={{ fill:"#555",fontSize:10,fontFamily:"'IBM Plex Mono',monospace" }}
                tickLine={false} axisLine={false} width={36}
                tickFormatter={v => `${v}位`} />
              {!zoomTop6 && (
                <ReferenceLine y={4} stroke="#FFD70044" strokeDasharray="4 2"
                  label={{ value:"CL圏",fill:"#FFD70088",fontSize:9,position:"right" }} />
              )}
              <ReferenceLine y={1} stroke="#FFD70066" strokeDasharray="2 2" />
              {visibleSeasons.includes(cfg.threePointSeason) && (
                <ReferenceLine x={cfg.threePointSeason}
                  stroke="#FF8C0099" strokeWidth={1.5} strokeDasharray="4 3"
                  label={{ value:"3pt制", fill:"#FF8C00cc", fontSize:9, position:"insideTopLeft", offset:4 }} />
              )}
              <Tooltip content={<Tooltip2 />} />
              {[...selected].map(team => (
                <Line key={team} type="monotone" dataKey={team}
                  stroke={POSITIONS[team]?.color || "#888"} strokeWidth={2}
                  dot={{ r:2,fill:POSITIONS[team]?.color || "#888" }}
                  activeDot={{ r:5,stroke:"#fff",strokeWidth:1 }}
                  connectNulls={false} />
              ))}
            </LineChart>
          </ResponsiveContainer>
        </div>

        {subView === "positions" && (
          <SeasonTable
            leagueKey={leagueKey}
            cfg={cfg}
            POSITIONS={POSITIONS}
            TEAM_NAMES_JP={TEAM_NAMES_JP}
            visibleSeasons={visibleSeasons}
            estimatePts={estimatePts}
          />
        )}

        {/* Trophy summary */}
        <div style={{ background:"#0b0c14",border:"1px solid #1a1a28",borderRadius:4,padding:"14px 16px",marginBottom:12 }}>
          <div style={{ fontSize:10,color:"#555",marginBottom:10,letterSpacing:2 }}>通算成績（選択チームのみ）</div>
          <div style={{ display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:8 }}>
            {[...selected].filter(t => POSITIONS[t] && trophies[t]).sort((a,b) => trophies[b].titles - trophies[a].titles).map(team => {
              const t = trophies[team];
              const c = POSITIONS[team]?.color || "#888";
              return (
                <div key={team} style={{ background:"#0e0e18",border:`1px solid ${c}44`,borderRadius:4,padding:"8px 10px" }}>
                  <div style={{ color:c,fontSize:11,fontWeight:700,marginBottom:4 }}>{TEAM_NAMES_JP[team] || team}</div>
                  <div style={{ fontSize:10,color:"#888",lineHeight:1.7 }}>
                    🏆 <span style={{ color:"#FFD700",fontWeight:700 }}>{t.titles}</span>
                    {" "}/ 🥈 <span style={{ color:"#aaa" }}>{t.runners}</span>
                    {" "}/ ✓Top4 <span style={{ color:"#06D6A0" }}>{t.top4}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
        </>)}

        {/* ── 累積勝ち点ビュー ── */}
        {subView === "cumpts" && (
          <div>
            <div style={{ background:"#0b0c14",border:"1px solid #1a1a28",borderRadius:4,padding:"20px 8px 12px 0",marginBottom:16 }}>
              <div style={{ textAlign:"center",fontSize:10,color:"#555",marginBottom:8,letterSpacing:1 }}>
                累積勝ち点（順位から推計） — {visibleSeasons[0]}〜{visibleSeasons[visibleSeasons.length-1]}
              </div>
              <ResponsiveContainer width="100%" height={440}>
                <LineChart data={cumPtsData} margin={{ top:8,right:24,left:0,bottom:30 }}>
                  <CartesianGrid stroke="#131320" strokeDasharray="3 3" />
                  <XAxis dataKey="season"
                    tick={{ fill:"#555",fontSize:9,fontFamily:"'IBM Plex Mono',monospace" }}
                    tickLine={false} axisLine={{ stroke:"#252535" }}
                    angle={-45} textAnchor="end"
                    interval={Math.max(0,Math.floor(visibleSeasons.length/24))} />
                  <YAxis
                    tick={{ fill:"#555",fontSize:10,fontFamily:"'IBM Plex Mono',monospace" }}
                    tickLine={false} axisLine={false} width={50}
                    tickFormatter={v => v > 999 ? `${(v/1000).toFixed(1)}k` : v} />
                  <Tooltip content={<CumTip />} />
                  {visibleSeasons.includes(cfg.threePointSeason) && (
                    <ReferenceLine x={cfg.threePointSeason}
                      stroke="#FF8C0099" strokeWidth={1.5} strokeDasharray="4 3"
                      label={{ value:"3pt制", fill:"#FF8C00cc", fontSize:9, position:"insideTopLeft", offset:4 }} />
                  )}
                  {[...selected].map(team => (
                    <Line key={team} type="monotone" dataKey={team}
                      stroke={POSITIONS[team]?.color || "#888"} strokeWidth={2}
                      dot={false} connectNulls activeDot={{ r:4 }} />
                  ))}
                </LineChart>
              </ResponsiveContainer>
            </div>
            {/* 通算W/D/L（累積勝ち点ビュー内） */}
            <div style={{ marginBottom:16 }}>
              {/* 3点制バナー */}
              <div style={{
                background:"#1a1200", border:"1px solid #FF8C0066",
                borderRadius:4, padding:"8px 14px", marginBottom:10,
                display:"flex", alignItems:"center", gap:10, flexWrap:"wrap",
              }}>
                <span style={{ fontSize:13 }}>🟠</span>
                <span style={{ fontSize:11, color:"#FF8C00", fontWeight:700 }}>
                  {cfg.threePointSeason}シーズンより3-1-0制に変更
                </span>
                <span style={{ fontSize:10, color:"#665500", marginLeft:4 }}>（それ以前は2-1-0制）</span>
                <span style={{ fontSize:10, color:"#443300", marginLeft:"auto" }}>※推計通算勝ち点はすべて3-1-0換算</span>
              </div>
              <div style={{ background:"#0b0c14",border:"1px solid #1a1a28",borderRadius:4,padding:"14px 16px",marginBottom:8 }}>
                <div style={{ fontSize:10,color:"#555",marginBottom:10,letterSpacing:2 }}>通算W/D/L</div>
                <div style={{ display:"flex",flexDirection:"column",gap:8 }}>
                  {[...selected].filter(t => POSITIONS[t] && ALL_WDL[t]).map(team => {
                    const wdl = ALL_WDL[team];
                    const total = wdl.w + wdl.d + wdl.l;
                    const wPct = (wdl.w/total)*100;
                    const dPct = (wdl.d/total)*100;
                    const lPct = (wdl.l/total)*100;
                    const c = POSITIONS[team]?.color || "#888";
                    return (
                      <div key={team}>
                        <div style={{ display:"flex",justifyContent:"space-between",marginBottom:4 }}>
                          <span style={{ fontSize:11,color:c,fontWeight:700 }}>{TEAM_NAMES_JP[team]||team}</span>
                          <div style={{ display:"flex",gap:10,alignItems:"center" }}>
                            <span style={{ fontSize:10,color:"#FFD700",fontFamily:"'IBM Plex Mono',monospace",fontWeight:700 }}>
                              {(wdl.w*3+wdl.d).toLocaleString()} pt
                            </span>
                            <span style={{ fontSize:10,color:"#555",fontFamily:"'IBM Plex Mono',monospace" }}>
                              {total.toLocaleString()} 試合
                            </span>
                          </div>
                        </div>
                        <div style={{ display:"flex",height:20,borderRadius:3,overflow:"hidden",marginBottom:4 }}>
                          <div style={{ width:`${wPct}%`,background:"#06D6A0",display:"flex",alignItems:"center",justifyContent:"center" }}>
                            {wPct > 8 && <span style={{ fontSize:9,color:"#000",fontWeight:700 }}>{wdl.w}</span>}
                          </div>
                          <div style={{ width:`${dPct}%`,background:"#888",display:"flex",alignItems:"center",justifyContent:"center" }}>
                            {dPct > 6 && <span style={{ fontSize:9,color:"#000" }}>{wdl.d}</span>}
                          </div>
                          <div style={{ width:`${lPct}%`,background:"#E63946",display:"flex",alignItems:"center",justifyContent:"center" }}>
                            {lPct > 8 && <span style={{ fontSize:9,color:"#fff",fontWeight:700 }}>{wdl.l}</span>}
                          </div>
                        </div>
                        <div style={{ display:"flex",gap:12,fontSize:9,color:"#555" }}>
                          <span style={{ color:"#06D6A0" }}>■ 勝 {wdl.w} ({wPct.toFixed(1)}%)</span>
                          <span style={{ color:"#888" }}>■ 分 {wdl.d} ({dPct.toFixed(1)}%)</span>
                          <span style={{ color:"#E63946" }}>■ 負 {wdl.l} ({lPct.toFixed(1)}%)</span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
              <div style={{ display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:8,marginBottom:16 }}>
                {[...selected].filter(t => POSITIONS[t] && ALL_WDL[t])
                  .sort((a,b) => {
                    const ra = ALL_WDL[a].w/(ALL_WDL[a].w+ALL_WDL[a].d+ALL_WDL[a].l);
                    const rb = ALL_WDL[b].w/(ALL_WDL[b].w+ALL_WDL[b].d+ALL_WDL[b].l);
                    return rb - ra;
                  }).map(team => {
                    const wdl = ALL_WDL[team];
                    const total = wdl.w + wdl.d + wdl.l;
                    const winRate = (wdl.w/total*100).toFixed(1);
                    const c = POSITIONS[team]?.color || "#888";
                    const estPts = wdl.w * 3 + wdl.d;
                    return (
                      <div key={team} style={{ background:"#0e0e18",border:`1px solid ${c}44`,borderRadius:4,padding:"10px 12px" }}>
                        <div style={{ color:c,fontSize:11,fontWeight:700,marginBottom:6 }}>{TEAM_NAMES_JP[team]||team}</div>
                        <div style={{ fontSize:10,color:"#888",lineHeight:1.9 }}>
                          <div>勝率 <span style={{ color:c,fontWeight:700 }}>{winRate}%</span></div>
                          <div>W <span style={{ color:"#06D6A0" }}>{wdl.w.toLocaleString()}</span>
                            {" "}/D <span style={{ color:"#aaa" }}>{wdl.d.toLocaleString()}</span>
                            {" "}/L <span style={{ color:"#E63946" }}>{wdl.l.toLocaleString()}</span></div>
                          <div>推計通算 <span style={{ color:"#FFD700",fontWeight:700 }}>{estPts.toLocaleString()} pt</span></div>
                        </div>
                      </div>
                    );
                  })}
              </div>
              <div style={{ fontSize:9,color:"#333",textAlign:"center",marginBottom:8 }}>
                ※ 各国1部リーグ全時代通算（推計値含む）。推計勝ち点=勝×3+分×1。
              </div>
            </div>

            {/* 最終累積ランキング */}
            <div style={{ background:"#0b0c14",border:"1px solid #1a1a28",borderRadius:4,padding:"14px 16px" }}>
              <div style={{ fontSize:10,color:"#555",marginBottom:10,letterSpacing:2 }}>
                累積勝ち点ランキング（{visibleSeasons[0]}〜{visibleSeasons[visibleSeasons.length-1]}）
              </div>
              <div style={{ display:"flex",flexDirection:"column",gap:6 }}>
                {[...selected]
                  .filter(t => POSITIONS[t])
                  .map(team => {
                    const last = cumPtsData[cumPtsData.length-1];
                    return { team, pts: last?.[team] || 0 };
                  })
                  .sort((a,b) => b.pts - a.pts)
                  .map(({ team, pts }, i) => {
                    const c = POSITIONS[team]?.color || "#888";
                    const maxPts = cumPtsData[cumPtsData.length-1];
                    const topPts = Math.max(...[...selected].filter(t=>POSITIONS[t]).map(t=>maxPts?.[t]||0));
                    const pct = topPts > 0 ? (pts/topPts)*100 : 0;
                    return (
                      <div key={team} style={{ display:"flex",alignItems:"center",gap:8 }}>
                        <span style={{ fontSize:10,color:"#444",width:16,textAlign:"right" }}>{i+1}</span>
                        <span style={{ fontSize:11,color:c,fontWeight:700,width:100,flexShrink:0 }}>
                          {TEAM_NAMES_JP[team]||team}
                        </span>
                        <div style={{ flex:1,background:"#111",borderRadius:2,height:14,overflow:"hidden" }}>
                          <div style={{ width:`${pct}%`,height:"100%",background:c,borderRadius:2,opacity:0.85 }} />
                        </div>
                        <span style={{ fontSize:11,color:c,fontFamily:"'IBM Plex Mono',monospace",fontWeight:700,minWidth:50,textAlign:"right" }}>
                          {pts.toLocaleString()} pt
                        </span>
                      </div>
                    );
                  })}
              </div>
              <div style={{ fontSize:9,color:"#333",marginTop:10 }}>
                ※ 各シーズンの順位から推計した累積勝ち点。実際の勝ち点とは誤差があります。
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

const qbtn = (color, dim=false) => ({
  background: dim ? "#111" : `${color}22`,
  color: color,
  border: `1px solid ${color}`,
  borderRadius: 3, padding:"4px 12px", fontSize:11, fontWeight:700, cursor:"pointer",
  fontFamily:"'Noto Sans JP',sans-serif",
});

