const UEFA_COLORS = {
  England: "#E63946", Germany: "#2ECC71", Spain: "#F5A623", Italy: "#00B4D8", France: "#9B5DE5",
  Portugal: "#FF6B35", Netherlands: "#FFD700", Belgium: "#A8DADC",
  "W.Germany": "#2ECC71", USSR: "#E63946", Turkey: "#EF233C", Czechia: "#B5838D",
};
const UEFA_DASH = {
  England:"0", Germany:"0", Spain:"0", Italy:"0", France:"0",
  Portugal:"5 3", Netherlands:"4 2", Belgium:"8 3",
  "W.Germany":"3 3", USSR:"3 3", Turkey:"6 2", Czechia:"2 2",
};
const UEFA_ALL_COUNTRIES = ["England","Spain","Germany","Italy","France","Portugal","Netherlands","Belgium","Turkey","Czechia","W.Germany","USSR"];
const UEFA_TOP5 = ["England","Spain","Germany","Italy","France"];

function UefaView() {
  const [selected, setSelected] = useState(new Set(UEFA_TOP5));
  const [yearStart, setYearStart] = useState(2000);

  const toggleCountry = (c) => setSelected(prev => {
    const n = new Set(prev); n.has(c) ? n.delete(c) : n.add(c); return n;
  });

  const chartData = useMemo(() => {
    const years = Object.keys(UEFA_RAW_DATA).map(Number).filter(y => y >= yearStart && y <= 2025).sort((a,b) => a-b);
    return years.map(year => {
      const row = { year: String(year) };
      [...selected].forEach(c => { row[c] = UEFA_RAW_DATA[year]?.[c] ?? null; });
      return row;
    });
  }, [selected, yearStart]);

  const Tip = ({ active, payload, label }) => {
    if (!active || !payload?.length) return null;
    const sorted = [...payload].filter(p => p.value != null).sort((a,b) => b.value - a.value);
    return (
      <div style={{ background:"#0a0a0a",border:"1px solid #333",borderRadius:4,padding:"10px 14px",fontFamily:"'IBM Plex Mono',monospace",fontSize:12,minWidth:180 }}>
        <div style={{ color:"#888",marginBottom:6,fontSize:11,letterSpacing:2 }}>SEASON {label}</div>
        {sorted.map(p => (
          <div key={p.dataKey} style={{ display:"flex",justifyContent:"space-between",gap:16,color:p.color,marginBottom:2 }}>
            <span>{p.dataKey}</span><span style={{ fontWeight:700 }}>{p.value?.toFixed(3)}</span>
          </div>
        ))}
      </div>
    );
  };

  return (
    <div>
      {/* Year range */}
      <div style={{ display:"flex",alignItems:"center",gap:16,marginBottom:20,justifyContent:"center" }}>
        <span style={{ fontSize:11,color:"#666",letterSpacing:2 }}>START</span>
        {[1984,1990,2000,2010,2018].map(y => (
          <button key={y} onClick={() => setYearStart(y)} style={{
            background: yearStart===y ? "#e8e8e8" : "transparent",
            color: yearStart===y ? "#000" : "#666",
            border:`1px solid ${yearStart===y?"#e8e8e8":"#333"}`,
            borderRadius:2,padding:"4px 12px",fontSize:11,cursor:"pointer",
            fontFamily:"'IBM Plex Mono',monospace",letterSpacing:1,
          }}>{y}</button>
        ))}
      </div>

      {/* Country toggles */}
      <div style={{ display:"flex",flexWrap:"wrap",gap:8,marginBottom:24,justifyContent:"center" }}>
        {UEFA_ALL_COUNTRIES.filter(c => c !== "USSR" || yearStart <= 1991).filter(c => c !== "W.Germany" || yearStart <= 1990).map(c => {
          const isOn = selected.has(c);
          const col = UEFA_COLORS[c] || "#aaa";
          return (
            <button key={c} onClick={() => toggleCountry(c)} style={{
              background: isOn ? col : "transparent",
              color: isOn ? "#fff" : "#555",
              border:`1px solid ${isOn ? col : "#333"}`,
              borderRadius:2,padding:"4px 12px",fontSize:11,cursor:"pointer",
              fontFamily:"'IBM Plex Mono',monospace",letterSpacing:1,
            }}>{c}</button>
          );
        })}
      </div>

      {/* Chart */}
      <div style={{ background:"#0d0d0f",border:"1px solid #1e1e22",borderRadius:4,padding:"24px 8px 8px 8px",marginBottom:16 }}>
        <ResponsiveContainer width="100%" height={400}>
          <LineChart data={chartData} margin={{ top:8,right:24,left:0,bottom:8 }}>
            <CartesianGrid stroke="#1a1a1e" strokeDasharray="3 3" />
            <XAxis dataKey="year" tick={{ fill:"#555",fontSize:10,fontFamily:"'IBM Plex Mono',monospace" }} tickLine={false} axisLine={{ stroke:"#333" }} interval={2} />
            <YAxis tick={{ fill:"#555",fontSize:10,fontFamily:"'IBM Plex Mono',monospace" }} tickLine={false} axisLine={false} width={50} tickFormatter={v => v.toFixed(0)} />
            <Tooltip content={<Tip />} />
            {[...selected].map(c => (
              <Line key={c} type="monotone" dataKey={c}
                stroke={UEFA_COLORS[c] || "#aaa"}
                strokeWidth={c === "England" || c === "Spain" ? 2.5 : 1.5}
                strokeDasharray={UEFA_DASH[c] || "0"}
                dot={false} connectNulls={false}
                activeDot={{ r:4, fill:UEFA_COLORS[c] || "#aaa" }} />
            ))}
          </LineChart>
        </ResponsiveContainer>
      </div>

      <div style={{ textAlign:"center",fontSize:10,color:"#444",letterSpacing:1,lineHeight:1.8 }}>
        UEFAカントリー係数（5年間累計）。Source: UEFA / Wikipedia
      </div>
    </div>
  );
}

// =============================================================
// OPTA POWER RANKINGS VIEW
// =============================================================

const OPTA_LEAGUE_CFG = {
  J1:  { label:"J1",          color:"#F5A623", bg:"#1a1200" },
  PL:  { label:"プレミア",     color:"#00B4D8", bg:"#001520" },
  CH:  { label:"チャンプ",     color:"#5BC0EB", bg:"#00111a" },
  BUN: { label:"ブンデス",     color:"#E63946", bg:"#1e0004" },
  LAL: { label:"ラ・リーガ",   color:"#9B5DE5", bg:"#130020" },
  SA:  { label:"セリエA",      color:"#06D6A0", bg:"#001f16" },
  L1:  { label:"リーグ1",      color:"#F77F00", bg:"#1f1000" },
  POR: { label:"ポルトガル",   color:"#EF233C", bg:"#200009" },
  BEL: { label:"ベルギー",     color:"#FFD700", bg:"#1a1700" },
  NED: { label:"オランダ",     color:"#FF6B35", bg:"#1f0e00" },
};
const OPTA_ORDER = ["J1","PL","CH","BUN","LAL","SA","L1","POR","BEL","NED"];

function computePositions(clubs, colX, colSpan, ratingToY) {
  const sorted = [...clubs].sort((a,b) => b.rating - a.rating);
  const positions = [];
  sorted.forEach((club,i) => {
    const x = colX + (colSpan / (sorted.length + 1)) * (i + 1);
    const y = ratingToY(club.rating);
    positions.push({ ...club, x, y, labelY: y });
  });
  const MIN_GAP = 12;
  for (let iter = 0; iter < 10; iter++) {
    for (let i = 1; i < positions.length; i++) {
      const prev = positions[i-1];
      const curr = positions[i];
      if (Math.abs(curr.labelY - prev.labelY) < MIN_GAP) {
        const mid = (prev.labelY + curr.labelY) / 2;
        prev.labelY = mid - MIN_GAP/2;
        curr.labelY = mid + MIN_GAP/2;
      }
    }
  }
  return positions;
}

function OptaView() {
  const [hovered, setHovered] = useState(null);
  const [active, setActive] = useState(new Set(OPTA_ORDER));
  const [minRating, setMinRating] = useState(65);

  const toggleLeague = (l) => setActive(prev => {
    const n = new Set(prev); n.has(l) ? n.delete(l) : n.add(l); return n;
  });

  const filtered = useMemo(() => OPTA_CLUBS.filter(c => active.has(c.league) && c.rating >= minRating), [active, minRating]);
  const leagueOrder = OPTA_ORDER.filter(l => active.has(l));
  const numLeagues = leagueOrder.length;
  const W = Math.max(900, numLeagues * 130);
  const H = 860;
  const PAD = { top:60,bottom:50,left:55,right:20 };
  const chartW = W - PAD.left - PAD.right;
  const chartH = H - PAD.top - PAD.bottom;
  const colWidth = chartW / Math.max(numLeagues, 1);
  const minR = 65, maxR = 102;
  const ratingToY = (r) => PAD.top + chartH * (1 - (r - minR) / (maxR - minR));

  const allPositions = useMemo(() => {
    let result = [];
    leagueOrder.forEach((league, colIdx) => {
      const clubs = filtered.filter(c => c.league === league);
      const colX = PAD.left + colIdx * colWidth;
      const positions = computePositions(clubs, colX, colWidth, ratingToY);
      result = [...result, ...positions];
    });
    return result;
  }, [filtered, leagueOrder, colWidth]);

  const yTicks = [];
  for (let r = 70; r <= 100; r += 5) yTicks.push(r);

  return (
    <div>
      <div style={{ textAlign:"center",marginBottom:12 }}>
        <div style={{ fontSize:11,color:"#555" }}>2026年4月 — {filtered.length}クラブ表示中</div>
      </div>

      <div style={{ display:"flex",justifyContent:"center",gap:6,marginBottom:10,flexWrap:"wrap" }}>
        {OPTA_ORDER.map(l => {
          const cfg = OPTA_LEAGUE_CFG[l];
          const on = active.has(l);
          return (
            <button key={l} onClick={() => toggleLeague(l)} style={{
              background: on ? cfg.color : "#1a1a1a",
              color: on ? "#000" : "#555",
              padding:"4px 12px",borderRadius:20,fontSize:11,cursor:"pointer",border:"none",
              fontFamily:"'Noto Sans JP',sans-serif",fontWeight:700,opacity: on ? 1 : 0.45,
            }}>{cfg.label}</button>
          );
        })}
        <div style={{ display:"flex",alignItems:"center",gap:6,marginLeft:6 }}>
          <span style={{ fontSize:10,color:"#444" }}>最低: {minRating}</span>
          <input type="range" min={65} max={90} value={minRating}
            onChange={e => setMinRating(Number(e.target.value))}
            style={{ width:80, accentColor:"#888" }} />
        </div>
      </div>

      <div style={{ overflowX:"auto" }}>
        <svg width={W} height={H} style={{ display:"block",margin:"0 auto" }}>
          <rect x={0} y={0} width={W} height={H} fill="#080810" rx={6} />
          {yTicks.map(r => {
            const y = ratingToY(r);
            return (
              <g key={r}>
                <line x1={PAD.left} x2={W-PAD.right} y1={y} y2={y}
                  stroke={r%10===0?"#1e1e2e":"#111118"}
                  strokeWidth={r%10===0?1:0.5} />
                <text x={PAD.left-6} y={y+4} textAnchor="end"
                  fill={r%10===0?"#444":"#2a2a3a"} fontSize={r%10===0?10:8}
                  fontFamily="IBM Plex Mono">{r}</text>
              </g>
            );
          })}
          {leagueOrder.map((league, colIdx) => {
            const cfg = OPTA_LEAGUE_CFG[league];
            const x = PAD.left + colIdx * colWidth;
            const isLong = league === "CH";
            return (
              <g key={league}>
                <rect x={x+1} y={PAD.top} width={colWidth-2} height={chartH} fill={cfg.bg} opacity={0.6} rx={2} />
                {isLong ? (
                  <>
                    <text x={x+colWidth/2} y={H-26} textAnchor="middle" fill={cfg.color} fontSize={11} fontFamily="'Noto Sans JP',sans-serif" fontWeight={700}>チャンプ</text>
                    <text x={x+colWidth/2} y={H-13} textAnchor="middle" fill={cfg.color} fontSize={11} fontFamily="'Noto Sans JP',sans-serif" fontWeight={700}>シップ</text>
                  </>
                ) : (
                  <text x={x+colWidth/2} y={H-14} textAnchor="middle" fill={cfg.color} fontSize={12} fontFamily="'Noto Sans JP',sans-serif" fontWeight={700}>{cfg.label}</text>
                )}
              </g>
            );
          })}
          {allPositions.map((club) => {
            const cfg = OPTA_LEAGUE_CFG[club.league];
            const isHov = hovered?.name === club.name && hovered?.league === club.league;
            return (
              <g key={`${club.league}-${club.name}`}
                onMouseEnter={() => setHovered(club)}
                onMouseLeave={() => setHovered(null)}
                style={{ cursor:"pointer" }}>
                {Math.abs(club.y - club.labelY) > 3 && (
                  <line x1={club.x} y1={club.y} x2={club.x+5} y2={club.labelY} stroke={cfg.color} strokeWidth={0.4} opacity={0.3} />
                )}
                <circle cx={club.x} cy={club.y} r={isHov ? 5.5 : 3.5} fill={cfg.color} opacity={isHov ? 1 : 0.88} />
                {club.rating >= minRating && (
                  <text x={club.x+6} y={club.labelY+3.5}
                    fill={isHov ? "#fff" : "#999"} fontSize={isHov ? 10.5 : 8.5}
                    fontFamily="'Noto Sans JP',sans-serif" fontWeight={isHov?700:400}
                    style={{ pointerEvents:"none" }}>
                    {club.name} ({club.rating})
                  </text>
                )}
              </g>
            );
          })}
        </svg>
      </div>
    </div>
  );
}

// =============================================================
// MAIN APP
// =============================================================

const TOP_TABS = [
  { key:"wc",   label:"ワールドカップ",      desc:"W杯重み付きスコア" },
  { key:"uefa", label:"カントリーランキング", desc:"UEFA国別係数" },
  { key:"opta", label:"パワーランキング v2", desc:"Optaクラブ実力" },
  { key:"big5", label:"5大リーグ歴代順位",   desc:"プレミア・ラリーガ他" },
];

export default function App() {
  const [topTab, setTopTab] = useState("big5");
  const [league, setLeague] = useState("PL");

  return (
    <div style={{ background:"#07080e",minHeight:"100vh",color:"#ccc",fontFamily:"'Noto Sans JP','IBM Plex Mono',monospace",padding:"20px 14px" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;700&family=IBM+Plex+Mono:wght@400;700&family=Bebas+Neue&display=swap');
        *{box-sizing:border-box}
        button{transition:all .12s}
        button:hover{opacity:.85}
      `}</style>

      {/* Master header */}
      <div style={{ textAlign:"center",marginBottom:20 }}>
        <div style={{ fontFamily:"'Bebas Neue'",fontSize:32,letterSpacing:5,color:"#fff",lineHeight:1 }}>
          FOOTBALL STATS HUB
        </div>
        <div style={{ fontSize:10,color:"#444",letterSpacing:3,marginTop:4 }}>
          W杯 / UEFA / OPTA / TOP 5 LEAGUES
        </div>
      </div>

      {/* Top-level tabs */}
      <div style={{ display:"flex",justifyContent:"center",gap:8,marginBottom:18,flexWrap:"wrap" }}>
        {TOP_TABS.map(t => (
          <button key={t.key} onClick={() => setTopTab(t.key)} style={{
            background: topTab===t.key ? "linear-gradient(135deg, #9B5DE5, #4A90D9)" : "#0e0e18",
            color: topTab===t.key ? "#fff" : "#666",
            border:`1px solid ${topTab===t.key?"#7C4DFF":"#222"}`,
            borderRadius:4,padding:"10px 18px",fontSize:12,cursor:"pointer",
            fontFamily:"'Noto Sans JP',sans-serif",fontWeight:topTab===t.key?700:400,
            display:"flex",flexDirection:"column",alignItems:"center",gap:2,minWidth:140,
          }}>
            <span>{t.label}</span>
            <span style={{ fontSize:9, opacity:0.7 }}>{t.desc}</span>
          </button>
        ))}
      </div>

      {/* Section title */}
      <div style={{ textAlign:"center",marginBottom:16 }}>
        <div style={{ fontSize:20,fontWeight:700,color:"#fff",letterSpacing:2,fontFamily:"'Bebas Neue'" }}>
          {TOP_TABS.find(t => t.key === topTab)?.label}
        </div>
      </div>

      {topTab === "wc"   && <WorldCupView />}
      {topTab === "uefa" && <UefaView />}
      {topTab === "opta" && <OptaView />}
      {topTab === "big5" && (
        <>
          {/* Sub-tabs for big5 */}
          <div style={{ display:"flex",justifyContent:"center",gap:6,marginBottom:18,flexWrap:"wrap" }}>
            {LEAGUE_KEYS.map(k => {
              const cfg = LEAGUE_CONFIG[k];
              const on = league === k;
              return (
                <button key={k} onClick={() => setLeague(k)} style={{
                  background: on ? cfg.color : "#0e0e18",
                  color: on ? "#000" : "#666",
                  border:`1px solid ${on?cfg.color:"#222"}`,
                  borderRadius:3,padding:"6px 14px",fontSize:11,cursor:"pointer",
                  fontFamily:"'Noto Sans JP',sans-serif",fontWeight:on?700:400,
                }}>{cfg.label}</button>
              );
            })}
          </div>
          <LeagueHistoryView key={league} leagueKey={league} />
        </>
      )}

      <div style={{ textAlign:"center",fontSize:9,color:"#252535",marginTop:30,lineHeight:1.8 }}>
        統合フットボール統計アプリ — UEFA国別係数 / Optaパワーランキング / 5大リーグ歴代順位
      </div>
    </div>
  );
}